<script setup>
import {ref,watch,nextTick} from 'vue';import {router,usePage} from '@inertiajs/vue3';import axios from 'axios';import {art,message} from '../art';
const page=usePage(),dialog=ref(null),busy=ref(false),error=ref('');
async function open(){await nextTick();if(page.props.featureUpdate&&!dialog.value?.open)dialog.value?.showModal()}
watch(()=>[page.props.featureUpdate?.release,page.props.featureUpdate?.unread,page.props.user?.id],()=>{if(page.props.featureUpdate?.unread)open()},{immediate:true});
async function close(url){if(busy.value)return;busy.value=true;error.value='';try{await axios.post('/feature-updates/read',{release:page.props.featureUpdate.release});page.props.featureUpdate.unread=false;dialog.value.close();if(url)router.visit(url)}catch(e){error.value=message(e)}finally{busy.value=false}}
defineExpose({open});
</script>
<template><dialog ref="dialog" class="journey-dialog whats-new" aria-labelledby="whats-new-title" @cancel.prevent="close()"><div class="journey-header"><img class="small-portrait" :src="art.logo" alt="SUSHI"><div><p class="eyebrow">What's new · SUSHI v{{page.props.featureUpdate?.version}}</p><h2 id="whats-new-title">{{page.props.featureUpdate?.title}}</h2></div></div><div class="journey-scroll"><p class="release-summary">{{page.props.featureUpdate?.summary}}</p><article v-for="feature in page.props.featureUpdate?.features" :key="feature.title"><h3>{{feature.title}}</h3><p>{{feature.text}}</p><button class="plain" :disabled="busy" @click="close(feature.url)">Explore →</button></article></div><div class="new-actions"><p>You can reopen this from your account menu.</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="busy" @click="close()">Got it. Let's roll!</button></div></dialog></template>
<style scoped>.whats-new{width:min(720px,calc(100% - 24px));height:fit-content;max-height:calc(100dvh - 32px);margin:auto;border-radius:24px}.whats-new .journey-header{grid-template-columns:auto minmax(0,1fr);gap:16px;padding-bottom:18px}.whats-new .journey-header h2{margin-bottom:0}.whats-new article{padding:16px 0;border-bottom:1px solid #efd7df}.whats-new article h3{margin:0}.new-actions{padding:12px 24px 20px;flex-shrink:0}.new-actions p{font-size:.85rem}.whats-new .journey-scroll{max-height:55dvh;flex:0 1 auto}@media(max-width:550px){.whats-new .journey-header{gap:12px}.whats-new .journey-header h2{font-size:23px}.new-actions .primary{width:100%}}</style>
